query getStaticAlertTimeSeries(
  $monitorUuid: String!
  $contextHash: String!
  $timeFrame: IssueTimeFrameForWidget!
) {
  timeSeriesIssuePeriods(
    monitorUuid: $monitorUuid
    contextHash: $contextHash
    timeFrame: $timeFrame
  ) {
    periods {
      fromDate
      toDate
    }
    count
  }
}
